with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , CUMULATIVE_BONUS_RATE as CUMULATIVE_BONUS_PERCENTAGE
        , CUMULATIVE_BONUS_AMT as BONUS_AMOUNT
        , cast(null as varchar) as NCB_PERCENTAGE
        , 'BA_HCP_DT_PREMIUM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_dt_premium') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POL_SERIAL_NO))) as HUB_POLICY_HK
        , PLC_CB_PER as CUMULATIVE_BONUS_PERCENTAGE
        , PLC_CB_AMOUNT as BONUS_AMOUNT
        , cast(null as varchar) as NCB_PERCENTAGE
        , 'BA_HCP_PROD_8433_FHC_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8433_fhc_loader') }}
    where (nullif(trim(POL_SERIAL_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , CUMULATIVE_BNOUZ_PER as CUMULATIVE_BONUS_PERCENTAGE
        , CUMULATIVE_AMT as BONUS_AMOUNT
        , cast(null as varchar) as NCB_PERCENTAGE
        , 'BJAZ_HCF_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcf_member_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , CUMM_BONUS_PER as CUMULATIVE_BONUS_PERCENTAGE
        , CUMM_BONUS as BONUS_AMOUNT
        , cast(null as varchar) as NCB_PERCENTAGE
        , 'BJAZ_HM_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , CUMM_BONUS_PER as CUMULATIVE_BONUS_PERCENTAGE
        , CUMM_BONUS as BONUS_AMOUNT
        , cast(null as varchar) as NCB_PERCENTAGE
        , 'BJAZ_IHG_MEM_DTLS_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ihg_mem_dtls_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , CUMM_BONUS_PER as CUMULATIVE_BONUS_PERCENTAGE
        , CUMM_BONUS as BONUS_AMOUNT
        , cast(null as varchar) as NCB_PERCENTAGE
        , 'BJAZ_SH_MEM_DTLS_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_sh_mem_dtls_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as CUMULATIVE_BONUS_PERCENTAGE
        , BONUS as BONUS_AMOUNT
        , cast(null as varchar) as NCB_PERCENTAGE
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(POLICY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , CB_PER as CUMULATIVE_BONUS_PERCENTAGE
        , CB_AMT as BONUS_AMOUNT
        , cast(null as varchar) as NCB_PERCENTAGE
        , 'BJAZ_STARPKG_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_starpkg_pol_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as CUMULATIVE_BONUS_PERCENTAGE
        , cast(null as varchar) as BONUS_AMOUNT
        , NCB_RATE as NCB_PERCENTAGE
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CUMULATIVE_BONUS_PERCENTAGE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then CUMULATIVE_BONUS_PERCENTAGE end)) as CUMULATIVE_BONUS_PERCENTAGE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BONUS_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then BONUS_AMOUNT end)) as BONUS_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then NCB_PERCENTAGE end) as NCB_PERCENTAGE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when CUMULATIVE_BONUS_PERCENTAGE is not null or BONUS_AMOUNT is not null or NCB_PERCENTAGE is not null
                     then md5(upper(coalesce(cast(CUMULATIVE_BONUS_PERCENTAGE as varchar), '') || '|' || coalesce(cast(BONUS_AMOUNT as varchar), '') || '|' || coalesce(cast(NCB_PERCENTAGE as varchar), '')))
                end as SAT_POLICY_BONUS_TRACKING_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_BONUS_TRACKING_HASHDIFF is not null
